<template><details class="card p-4 mt-5"><summary class="font-bold cursor-pointer">Группы мастерской</summary><p class="text-xs text-muted my-3">Группа связывает занятия, тарифы и абонементы. Новая группа создаётся при добавлении занятия с новым названием. Переименование не меняет оплаченные условия абонементов.</p><div v-for="g in groups()" :key="g.id" class="flex justify-between border-b py-3"><span>{{g.title}} · {{g.is_individual?'индивидуально':g.capacity+' мест'}}</span><button class="btn-quiet" @click="edit(g)">Изменить</button></div></details><BottomSheet :open="!!selected" title="Изменить группу" @close="selected=null"><form v-if="selected" @submit.prevent="save" class="space-y-3"><label class="label">Название<input class="field" v-model="selected.title" required maxlength="200"></label><label class="label">Количество мест<input class="field" type="number" min="1" max="1000" :disabled="selected.is_individual" v-model.number="selected.capacity" required></label><label class="label">Описание<textarea class="field" v-model="selected.description"></textarea></label><button :disabled="busy" class="btn-primary">Сохранить</button></form></BottomSheet></template>
<script setup lang="ts">import {ref} from 'vue';import BottomSheet from './BottomSheet.vue';import {api} from '../shared/api';import {useDemo,refresh} from '../shared/use-demo';const {groups}=useDemo();const selected=ref<any>(null),busy=ref(false);function edit(g:any){selected.value={...g}}async function save(){busy.value=true;try{const g=selected.value;await api('/master/groups/'+g.id,'PATCH',{expected_version:g.version,title:g.title,capacity:g.capacity,description:g.description||''});await refresh();selected.value=null;}finally{busy.value=false;}}</script>
